template <class T, class D>
struct std::hash<std::unique_ptr<T, D>> {
    using argument_type = std::unique_ptr<T, D>;
    using result_type = std::size_t;

    result_type operator()(const argument_type& p) const {
        // Hashing the unique_ptr requires hashing the raw pointer
        using RawPtr = T*;
        return std::hash<RawPtr>{}(p.get());
    }
};
